    :param all: If True, include hidden attributes as well.
    :returns: A list of tuples with attribute names and descriptions.
    """

    try:
        ifaces = self._interface
    except AttributeError:
        return []

    result = []
    for name, anno in six.iteritems(ifaces):
        if anno.name:
            result.append((name, anno.description))

    if all:
        for name, anno in six.iteritems(self._attributes):
            if anno.name:
                result.append((name, anno.description))

    return result

def namesAndDescriptions(self, all=False):
    """
    Return attribute names and descriptions defined by interface.

    Args:
        all (bool): If True, include inherited attributes.

    Returns:
        dict: Mapping of attribute names to descriptions.
    """

    if all:
        names = self.__dict__
    else:
        names = self.__dict__.copy()
        for name in dir(self):
            if name.startswith('_'):
                names.pop(name)

    result = {}
    for name, value in names.items():
        doc = inspect.getdoc(value)
        if doc:
            result[name] = doc

    return result

def namesAndDescriptions(self, all=False):
    """
    Return attribute names and descriptions defined by interface.

    Args:
      all (bool): If True, include attributes inherited from parents.

    Returns:
      Dict: Dictionary with attribute names as keys and descriptions as values.
    """
    names_and_descriptions = {}
    for name, attribute in self.__dict__.items():
        if all or name in self.__dict__:
            # If the attribute is a function, get its docstring. Otherwise,
            # use the default description.
            if callable(attribute):
                description = attribute.__doc__
            else:
                description = "No description."
            names_and_descriptions[name] = description
    return names_and_descriptions

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if all:
        return list(self.__dict__.keys())
    else:
        return [name for name, _ in self._attrs if not name.startswith('_')]

