def patched_normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if isinstance(sequence, (Declaration, tuple)):
        output.append(sequence)
    elif isinstance(sequence, Interface):
        for name in sequence.names():
            output.append(name)
    elif isinstance(sequence, list):
        for s in sequence:
            patched_normalizeargs(s, output)
    elif isinstance(sequence, InterfaceSpec):
        for name in sequence.names:
            output.append(name)
    else:
        raise TypeError("Unsupported argument type: {}".format(type(sequence)))

    return output

