import copy

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field_name, field in observer_schema.items():
        if field["observed_fields"] is not None:
            for observed_field in field["observed_fields"]:
                if observed_field not in response:
                    # If the observed field is not present in the response, raise a KeyError
                    raise KeyError("Response does not contain observed field '{}' for field '{}'".format(observed_field, field_name))
                if field_name not in last_applied_manifest:
                    # If the field is not yet present in the last_applied_manifest, initialize it
                    last_applied_manifest[field_name] = {}
                last_applied_manifest[field_name][observed_field] = response[observed_field]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        resource_type = resource["kind"]
        if resource_type not in app.spec.observer_schemas:
            app.spec.observer_schemas[resource_type] = {
                "metrics": [
                    {
                        "name": "value",
                        "type": "byte"
                    }
                ]
            }
    app.save()

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: The formatted SQL query and the converted out-style parameters.
    :rtype: tuple
    """
    if self.in_style == SQLParams.NONE:
        raise ValueError("No parameters set")

    if self.in_style == SQLParams.NAMED:
        if not isinstance(params, dict):
            raise ValueError("Expected dict as parameter")
        formatted_params = {f":{key}": value for key, value in params.items()}
        sql = sql % formatted_params
    elif self.in_style == SQLParams.ORDINAL:
        if not isinstance(params, list):
            raise ValueError("Expected list as parameter")
        formatted_params = {index: value for index, value in enumerate(params, start=1)}
        sql = sql % formatted_params
    else:
        raise ValueError(f"Invalid parameter style: {self.in_style}")

    return sql, formatted_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: AnyStr
    :param params: The set of in-style parameters.
    :type params: Union[Dict[Union[str, int], Any], Sequence[Any]]
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]
    """
    if self.in_style == 'named':
        if not isinstance(params, Dict):
            raise TypeError("'params' must be of type Dict when 'in_style' is 'named'")
    else:
        if not isinstance(params, Sequence):
            raise TypeError("'params' must be of type Sequence when 'in_style' is 'ordinal'")
    formatted_sql = sql
    converted_params = {}
    if self.in_style == 'named':
        for param, value in params.items():
            param_placeholder = ':' + param
            formatted_sql = formatted_sql.replace(param_placeholder, '%s')
            converted_params[param_placeholder] = value
    else:
        for index, value in enumerate(params):
            param_placeholder = '?'
            formatted_sql = formatted_sql.replace(param_placeholder, '%s')
            converted_params[param_placeholder] = value
    return (formatted_sql, converted_params)

