def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        raise ValueError('path must be provided')

    if not os.path.isdir(path) and not os.path.basename(path) == 'root':
        raise NotADirectoryError('path must be a directory or the pyfs root')

    # Validate OCFL root
    root = os.path.join(path, 'root')
    if not os.path.isdir(root):
        raise OCFLRootError('failed to locate OCFL root directory: {}'.format(root))

    # Validate OCFL identity
    identity = os.path.join(root, 'fcr-ocfl-1.0.json')
    if not os.path.isfile(identity):
        raise OCFLIdentityError('failed to locate OCFL identity file: {}'.format(identity))

    # Validate OCFL extension
    extension = os.path.join(root, '.ocfl_setspec')
    if not os.path.isfile(extension):
        raise OCFLExtensionError('failed to locate OCFL extension file: {}'.format(extension))

    # Validate OCFL inventory
    inventory = os.path.join(root, 'inventory.json')
    if not os.path.isfile(inventory):
