    xml_basenames = [os.path.basename(xml_fn) for xml_fn in xml_filename]
    xml_files = [fn for fn in files if os.path.basename(fn) in xml_basenames]
    file_dict = {xml_fn: [] for xml_fn in xml_filename}
    for xml_file in xml_files:
