def _eval_file(prefix, file_path):
    """
    Identifies the file type of the package: `asset` or `rendition`.

    Identifies the file type of the package and updates `packages` with the type and
    the file address being analyzed.

    Parameters
    ----------
    prefix : str
        File name without extension
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    # Verify that the file is an XML file
    if file_path.endswith(".xml"):
        with open(file_path, "r") as xml_file:
            xml_root = xml_file.read()
            if xml_root.find(".//vnd.adobe/xe/asset") != -1:
                return {"type": "asset", "file": file_path}
            elif xml_root.find(".//vnd.adobe/xe/rendition") != -1:
                return {"type": "rendition", "file": file_path}
            else:
                return {}
    else:
        return {}

