def _explore_zipfile(zip_path):
    zip_file = zipfile.ZipFile(zip_path, mode='r')
    files = zip_file.namelist()
    packages = {}
    for file in files:
        if file.endswith('.xml'):
            base = os.path.basename(file)
            if base not in packages:
                packages[base] = {}
            packages[base][file] = zip_file.read(file)
    return packages

