def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('GB'):
        return int(float(size[:-2]) * 1024 * 1024 * 1024)
    elif size.endswith('MB'):
        return int(float(size[:-2]) * 1024 * 1024)
    elif size.endswith('KB'):
        return int(float(size[:-2]) * 1024)
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """Returns the decimal representation of a human readable file size.

    The resulting value is an approximation as the input value is usually rounded.

    :param size: A string representing a human readable file size (e.g., '500K')
    :return: A decimal representation of file size
    :rtype: int

    Examples:
        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    if not size:
        return 0

    size_unit = size[-2:]
    size_value = int(size[:-2])

    if size_unit == 'KB':
        size_value *= 1024
    elif size_unit == 'MB':
        size_value *= 1024 ** 2
    elif size_unit == 'GB':
        size_value *= 1024 ** 3
    elif size_unit == 'TB':
        size_value *= 1024 ** 4
    elif size_unit == 'PB':
        size_value *= 1024 ** 5
    elif size_unit == 'EB':
        size_value *= 1024 ** 6
    elif size_unit == 'ZB':
        size_value *= 1024 ** 7
    elif size_unit == 'YB':
        size_value *= 1024 ** 8

    return size_value

