def addignored(ignored):
    """
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.
    """
    try:
        # Run the "git status" command to obtain the list of ignored files
        cmd = ["git", "status", "--ignored"]
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            raise Exception("Error running git status")

        # Filter the list of ignored files to only include those that have been deleted
        ignored_files = []
        for line in stdout.decode("utf-8").splitlines():
            if line.startswith("D"):
                # Delete the file from the repository
                cmd = ["git", "clean", "-X", "-f", "--", line[2:]]
                process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                stdout, stderr = process.communicate()
                if process.returncode != 0:
                    raise Exception("Error running git clean")
                ignored_files.append(line[2:])

        # Sort the list of ignored files and return them as a single string with each filename separated by a comma
        return ",".join(sorted(ignored_files))
    except Exception:
        return "Error adding ignored files to the repository"

