def from_ticks(ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight).

    :param ticks: nanoseconds since midnight
    :type ticks: int
    :param tz: optional timezone
    :type tz: datetime.tzinfo

    :rtype: Time

    :raises ValueError: if ticks is out of bounds
        (0 <= ticks < 86400000000000)
    """
    if not (0 <= ticks < 86400000000000):
        raise ValueError("Ticks is out of bounds (0 <= ticks < 86400000000000)")

    hours, minutes, seconds = floor(ticks / 3600000000000), floor(ticks / 60000000000), floor(ticks / 1000000000)
    nanoseconds = ticks - (hours * 3600000000000 + minutes * 6000000000 + seconds * 1000000000)

    if tz is not None:
        return Time(hour=hours, minute=minutes, second=seconds, nanosecond=nanoseconds, tzinfo=tz)
    else:
        return Time(hour=hours, minute=minutes, second=seconds, nanosecond=nanoseconds)

