def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise ValueError("'iface' must be a class")
    if not hasattr(candidate, "__class__"):
        raise ValueError("'candidate' must have a __class__ attribute")
    if not issubclass(candidate.__class__, iface):
        msg = "{} is not a subclass of {}".format(candidate.__class__, iface)
        raise ValueError(msg)

    if tentative:
        # If it's a tentative implementation, we'll just check that
        # the methods required by the interface exist and are callable.
        # We won't check that they have the correct signature or don't
        # crash when called, because that would be too complex.
        for attr in iface.__dict__:
            if iface.__dict__[attr].__module__ is not None:
                if attr not in candidate.__dict__:
                    raise ValueError("{} missing attribute".format(attr))
                if not callable(candidate.__dict__[attr]):
                    raise ValueError("{} not a callable".format(attr))
    else:
        # If it's a final implementation, we'll also check that the
        # methods have the correct signature and don't crash when called.
        for attr in iface.__dict__:
            method = candidate.__dict__[attr]
            if iface.__dict__[attr].__module__ is not None:
                if attr not in candidate.__dict__:
                    raise ValueError("{} missing attribute".format(attr))
                if not callable(method):
                    raise ValueError("{} not a callable".format(attr))
                if method.__code__ is not iface.__dict__[attr].__code__:
                    raise ValueError("{} has incorrect signature".format(attr))

        # Check that the class and its methods are final
        if not inspect.isclass(candidate):
            raise ValueError

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        try:
            for baseobj in base.infer(context=context):
                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    self._metaclass = baseobj._metaclass
                    self._metaclass_hack = True
                    break
        except exceptions.InferenceError:
            pass

    return self._metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    Args:
        bases (tuple): A tuple of class types to look through for metaclasses
        explicit_mc (class, optional): An optional explicit metaclass to use

    Returns:
        A class or None if a metaclass could not be determined
    """
    # Check if a metaclass was explicitly passed as a parameter
    if explicit_mc:
        return explicit_mc

    # Iterate through all the bases passed and find a metaclass
    for base in bases:
        # Handle situations where the base might be a subclass
        if hasattr(base, "__bases__"):
            # If the base has a metaclass, use it
            if hasattr(base, "__metaclass__"):
                return base.__metaclass__
            # Otherwise, check if the base has a __bases__ attribute
            for base_base in base.__bases__:
                if hasattr(base_base, "__metaclass__"):
                    return base_base.__metaclass__
        # If the base doesn't have a __bases__ attribute, it's a class
        else:
            if hasattr(base, "__metaclass__"):
                return base.__metaclass__

    # If no metaclass was found, return None
    return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    for base in bases:
        if not isinstance(base, (type, BaseType)):
            continue
        metaclass = base.__class__
        if issubclass(metaclass, type):
            return metaclass

    return base

def determineMetaclass(bases, explicit_mc):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    Args:
        bases (list): A list of base classes
        explicit_mc (object): An optional explicit __metaclass__

    Returns:
        object: The determined metaclass
    """
    # If we have exactly 1 base and we don't have an explicit_mc
    if len(bases) == 1 and explicit_mc is None:
        base = bases[0]
        try:
            if isinstance(base, (type, ClassDef)):
                return base._metaclass
        except exceptions.InferenceError:
            pass

    # If we have 1+ bases and no explicit_mc, default to type
    if len(bases) >= 1 and explicit_mc is None:
        for base in bases:
            if isinstance(base, (type, ClassDef)):
                return type

    # If we have no bases and no explicit_mc, default to object
    if len(bases) == 0 and explicit_mc is None:
        return object

    # If we have an explicit_mc, use it
    if explicit_mc is not None:
        return explicit_mc

    # If we don't have any known solution, return None
    return None

