    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        # Try to pop the key from the dict. If it's not found, raise a KeyError.
        value = self.pop(key)
    except KeyError:
        if default is not __marker:
            # If the default value is not None, return it.
            return default
        else:
            # If the default value is None, raise a KeyError.
            raise KeyError(f"Key {key} not found in dict.")
    return value

