    if key not in self.keys():
        if default is not None:
            return default
        raise KeyError(f"{key} not found in dictionary.")

    # Check if key is in the IntMap, FloatMap, StringMap, or BoolMap
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap, self._pb.BoolMap]:
