def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    converter = _converting._Converter()

    def _nested_convert(self, converter, source):
        """
        Recursively apply the converter to the source object.

        :param converter: The converter (:class:`._converting._Converter`).
        :param source: The source object.
        :return: The converted result.
        """
        if isinstance(source, dict):
            return {key: value for key, value in source.items()}
        elif isinstance(source, list):
            return [value for value in source]
        else:
            return source

    def _convert(self, source, converter):
        """
        Apply the converter to the source object.

        :param source: The source object.
        :param converter: The converter (:class:`._converting._Converter`).
        :return: The converted result.
        """
        if isinstance(source, str):
            return converter(source)
        elif isinstance(source, dict):
            return {key: value for key, value in source.items()}
        elif isinstance(source, list):
            return [value for value in source]
        else:
            return source

    def _parse(self, source, converter):
        """
        Parse the source object.

        :param source: The source object.
        :param converter: The converter (:class:`._converting._Converter`).
        :return: The parsed result.
        """
        if converter:
            result = self._convert(source, converter)
        else:
            result = source

        if isinstance(result, str):
            return result
        elif isinstance(result, dict):
            return {key: value for key, value in result.items()}
        elif isinstance(result, list):
            return [value for value in result]
        else:
            return result

    converter._nested_convert = _nested_convert
    converter._convert = _convert

