def dict_insert(dictionary, value, key, *subkeys):
    """
    Insert a value of a nested key into a dictionary.

    To insert a value for a nested key, all ancestor keys should be given as method arguments.

    Example:
        dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dictionary: The dictionary object to insert the nested key value into.
    :param value: The value to insert into the given dictionary.
    :param key: The first key in the key chain that will store the value.
    :param subkeys: The subkeys in the key chain.
    """
    if not dictionary:
        return {}

    if not subkeys:
        return {key: value}

    return {*dictionary, key: dict_insert(dictionary.get(key, {}), value, *subkeys)}

def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    To insert a value for a nested key, all ancestor keys should be given as
    method's arguments.

    Example:
        dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: A dictionary object to insert the nested key value into.
    :param val: A value to insert to the given dictionary.
    :param key: The first key in a chain of keys that will store the value.
    :param keys: The subkeys in the keys chain.
    """

    current_dict = dic

    try:
        for subkey in keys:
            if subkey not in current_dict:
                current_dict[subkey] = {}
            current_dict = current_dict[subkey]
        current_dict[key] = val
    except TypeError:
        raise ValueError("keys must be a string or a string array")
    except Exception as e:
        if "expected str, bytes or os.PathLike object, not dict" in str(e):
            raise ValueError("Dictionary key must be a string")
        else:
            raise e

