def validate_from_file(yaml_file):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise LookupError("yaml_file argument must be supplied")

    if not os.path.exists(yaml_file):
        raise Exception(f"yaml_file {yaml_file} does not exist")

    with open(yaml_file, "r") as file:
        try:
            data = yaml.safe_load(file)
        except yaml.YAMLError as exc:
            raise Exception(f"Error while loading YAML file: {exc}")

    if "ir_type" not in data:
        raise Exception(f"Missing IR type in {yaml_file}")

    if "ir_version" not in data:
        raise Exception(f"Missing IR version in {yaml_file}")

    if "mandatory" not in data:
        raise Exception(f"Missing mandatory fields in {yaml_file}")

    return data

