def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The resolved defaults for the current arguments.
    """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidArgumentError('Unable to resolve default for non-Option type')

        # get the default value from the spec if it exists
        if arg.spec and arg.default:
            defaults[arg.name] = arg.default

        # if we have a dict option, resolve the defaults for its spec
        # if the spec is valid and has any defaults, use them.
        if isinstance(arg, DictOption):
            if arg.spec:
                s = arg.spec
                if s.valid and s.defaults:
                    defaults[arg.name] = s.defaults

    return defaults

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources.

        Returns:
            dict: The resolved argument defaults.
        """
        defaults = {}
        for arg in self.spec.args:
            # check if there is a default set in the spec
            if not isinstance(arg, NoDefault):
                defaults[arg.name] = arg.default

            # check if there are any default values coming from the parent
            if hasattr(self.spec, 'parent') and self.spec.parent:
                # check if the arg name is in the parent spec
                if arg.name in self.spec.parent.args:
                    defaults[arg.name] = self.spec.parent.args[arg.name].default

            # if only the arg is a str and is a positional argument
            if isinstance(arg, str) and arg in self.spec.pos_args:
                # check if there is a corresponding cli argument
                if arg in self.spec.cli_args:
                    # copy the value
                    defaults[arg] = self.spec.cli_args[arg]

                # else check if there is a corresponding env var
                elif arg in self.spec.env_vars:
                    # get the env var name
                    env_var_name = self.spec.env_vars[arg].name
                    # copy the value
                    defaults[arg] = self.spec.env_vars[arg].value

        return defaults

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of resolved argument values.
    """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise TypeError(f'Unable to resolve default for non-Option type: {arg}')
        try:
            # try to get the value from the spec
            val = self._default_spec.get(arg.name)
        except KeyError:
            # use the default value if it exists
            if not isinstance(arg.default, _NoDefault):
                val = arg.default
            else:
                val = arg.default.default
        if arg.choices and val not in arg.choices:
            raise ValueError(f'Invalid choice: {val!r} (must be one of {arg.choices})')
        if arg.multi:
            if val:
                # convert comma-separated values to a list
                val = [x.strip() for x in val.split(',')]
        defaults[arg.name] = val
    return defaults

def get_spec_defaults(self):
