    """
    defaults = {}
    for arg_name, arg in self.spec.arguments.items():
        if not isinstance(arg, _BaseOpt):
            raise TypeError(f"Unable to resolve default for non-Option type: '{arg_name}'")

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg_name] = arg.default

        # if we have a dict option, resolve the defaults for its spec.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.spec:
                b = arg.spec.build_defaults()
                if b:
                    defaults[arg_name] = b
    return defaults

