def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is None:
        extra_vars = []

    if isinstance(vars_dict, dict) and isinstance(extra_vars, list):
        for key, value in enumerate(extra_vars):
            if key not in vars_dict:
                vars_dict.append(value)
            else:
                merge_extra_vars(vars_dict[key], extra_vars[key])
    else:
        raise ValueError('Unable to merge: Dictionnary and list expected')

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`"""
    if extra_vars is None:
        return vars_dict

    extra_vars_mapping = ensure_mapping_format(extra_vars)

    if not vars_dict:
        return extra_vars_mapping

    vars_dict_mapping = ensure_mapping_format(vars_dict)
    vars_dict_mapping.update(extra_vars_mapping)
    return vars_dict_mapping

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        if not isinstance(vars_dict, dict):
            raise ValueError("Unable to merge: `vars_dict` must be a dictionary")
        if not isinstance(extra_vars, list):
            raise ValueError("Unable to merge: `extra_vars` must be a list")
        vars_dict.update(extra_vars)
    return vars_dict

